+    transition: background 0.15s ease;
+}
+
+.btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+.btn-add-to-cart {
+    background: #0d6efd;
+    color: white;
+    margin-top: auto;
+}
+
+.btn-add-to-cart:hover:not(:disabled) {
+    background: #0b5ed7;
+}
+
+.btn-apply {
+    background: #0d6efd;
+    color: white;
+}
+
+.btn-apply:hover {
+    background: #0b5ed7;
+}
+
+.btn-clear {
+    background: #6c757d;
+    color: white;
+}
+
+.btn-clear:hover {
+    background: #5c636a;
+}
+
+.btn-retry {
+    background: #ffc107;
+    color: #000;
+    margin-left: 1rem;
+}
+
+/* Pagination */
+.catalog-pagination {
+    display: flex;
+    justify-content: center;
+    align-items: center;
+    gap: 0.25rem;
+    padding: 1rem 0;
+}
+
+.btn-page {
+    background: white;
+    border: 1px solid #dee2e6;
+    min-width: 2.5rem;
+    padding: 0.375rem 0.75rem;
+}
+
+.btn-page:hover:not(:disabled) {
+    background: #e9ecef;
+}
+
+.btn-page.active {
+    background: #0d6efd;
+    color: white;
+    border-color: #0d6efd;
+}
+
+/* States */
+.catalog-loading,
+.catalog-empty {
+    display: flex;
+    justify-content: center;
+    align-items: center;
+    min-height: 200px;
+    color: #6c757d;
+    font-size: 1.1rem;
+}
+
+.alert-error {
+    background: #f8d7da;
+    color: #842029;
+    padding: 1rem;
+    border-radius: 8px;
+    margin-bottom: 1rem;
+    display: flex;
+    align-items: center;
+}
+

